package org.jsoup.nodes;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.regex.Pattern;
import java.util.regex.PatternSyntaxException;
import org.jsoup.helper.StringUtil;
import org.jsoup.helper.Validate;
import org.jsoup.parser.Parser;
import org.jsoup.parser.Tag;
import org.jsoup.select.Collector;
import org.jsoup.select.Elements;
import org.jsoup.select.Evaluator;
import org.jsoup.select.Selector;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Element_previousElementSibling_TriageGen0Test {

    @Test
    public void testPreviousElementSibling_WithPreviousSibling() {
        // Setup a structure: <div><p>1</p><p>2</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p><p>2</p></div>");
        Element parent = doc.child(0);
        Element first = parent.child(0);
        Element second = parent.child(1);

        // Test: second element's previous sibling should be the first element
        Element result = second.previousElementSibling();

        assertNotNull(result);
        assertEquals("1", result.text());
        assertEquals(first, result);
    }

    @Test
    public void testPreviousElementSibling_FirstElementReturnsNull() {
        // Setup a structure: <div><p>1</p><p>2</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p><p>2</p></div>");
        Element parent = doc.child(0);
        Element first = parent.child(0);

        // Test: first element has no previous sibling, should return null
        Element result = first.previousElementSibling();

        assertNull(result);
    }

    @Test
    public void testPreviousElementSibling_SingleChildReturnsNull() {
        // Setup a structure: <div><p>1</p></div>
        Document doc = Parser.parseHtml("<div><p>1</p></div>");
        Element parent = doc.child(0);
        Element first = parent.child(0);

        // Test: single child has no previous sibling
        Element result = first.previousElementSibling();

        assertNull(result);
    }

    @Test(expected = NullPointerException.class)
    public void testPreviousElementSibling_OrphanElementThrowsException() {
        // Setup an element not attached to a parent
        // The method calls parent().children(). If parent() is null, it throws NPE.
        // Based on the provided code: List<Element> siblings = parent().children();
        Element orphan = new Element(org.jsoup.parser.Tag.valueOf("p"), "");

        // This should trigger NPE when calling parent()
        orphan.previousElementSibling();
    }
}
